import os
import argparse
from typing import Dict
import requests
import codecs
import pathlib

def dump_scalar_file(base_url: str, tag: str, run: str, file_format: str) -> str:
    """
    下载scalar指标文件
    """
    req = requests.get(url=base_url, params = {
        "tag": tag,
        "run": run,
        "format": file_format
    })
    req.raise_for_status()
    return req.text

def dump_scalars(base_url: str, scalar_mappings: Dict[str, str], save_folder: str, run: str = ".", file_format: str = "csv") -> None:
    """
    下载并保存指票文件
    """
    for file_name, tag in scalar_mappings.items():
        save_path = os.path.join(save_folder, f"{file_name}.{file_format}")
        file_content = dump_scalar_file(base_url, tag, run, file_format)
        with codecs.open(save_path, "w", encoding="utf-8") as f:
            f.write(file_content)
            print(f"{file_name} is dumped into {save_path}!")


